-----------------------------------------------------------\\\\n\\\\nnote_warning() { printf '%s\\\\\\\\n' \\\\\\\"$*\\\\\\\" >> \\\\\\\"$WARN_FILE\\\\\\\"; printf 'WARNING: %s\\\\\\\\n' \\\\\\\"$*\\\\\\\"; }\\\\n\\\\nrequire_tool() {\\\\n  # $1 = executable, $2 = how to install it\\\\n  if command -v \\\\\\\"$1\\\\\\\" >/dev/null 2>&1; then\\\\n    return 0\\\\n  fi\\\\n  printf 'ERROR: required tool %s is not on PATH.\\\\\\\\n' \\\\\\\"$1\\\\\\\"\\\\n  printf 'Install it with: %s\\\\\\\\n' \\\\\\\"$2\\\\\\\"\\\\n  exit \\\\\\\"$EXIT_TOOL_MISSING\\\\\\\"\\\\n}\\\\n\\\\nstep_build() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n\\\\n  # Warm .lake/build from the hot main snapshot before compiling.  The warmer\\\\n  # is the only writer of the shared snapshot; this worktree gets a private\\\\n  # copy-on-write clone (DESIGN.md invariant 1).\\\\n  if [ ! -d .lake/build ]; then\\\\n    if [ -x \\\\\\\"$SCRIPT_DIR/warm-worktree.sh\\\\\\\" ]; then\\\\n      echo \\\\\\\"+ warm-worktree.sh $WORKTREE\\\\\\\"\\\\n      if ! \\\\\\\"$SCRIPT_DIR/warm-worktree.sh\\\\\\\" \\\\\\\"$WORKTREE\\\\\\\"; then\\\\n        note_warning \\\\\\\"warm-worktree.sh failed for $WORKTREE; falling back to a cold build\\\\\\\"\\\\n      fi\\\\n    elif [ \\\\\\\"${MIPSTARRE_CI_REQUIRE_WARMER:-}\\\\\\\" = \\\\\\\"1\\\\\\\" ]; then\\\\n      printf 'ERROR: %s is missing and MIPSTARRE_CI_REQUIRE_WARMER=1.\\\\\\\\n' \\\\\\\"$SCRIPT_DIR/warm-worktree.sh\\\\\\\"\\\\n      exit \\\\\\\"$EXIT_TOOL_MISSING\\\\\\\"\\\\n    else\\\\n      note_warning \\\\\\\"local/bin/warm-worktree.sh not found; building $BRANCH from scratch (slow, but correct)\\\\\\\"\\\\n    fi\\\\n  fi\\\\n\\\\n  require_tool lake \\\\\\\"install elan (https://github.com/leanprover/elan) and re-run\\\\\\\"\\\\n\\\\n  # Two-tier cache, do not conflate (gotcha 1): .lake/build holds this\\\\n  # project's oleans and is per-worktree; .lake/packages holds Mathlib and\\\\n  # friends.  When packages is a symlink it points at the shared hot-main\\\\n  # tree and must be treated as read-only: `lake exe cache get` writes there.\\\\n  if [ -L .lake/packages ]; then\\\\n    echo \\\\\\\"+ .lake/packages is a shared symlink; skipping 'lake exe cache get' (read-only dependency tree)\\\\\\\"\\\\n  elif [ -d .lake/packages ]; then\\\\n    echo \\\\\\\"+ lake exe cache get\\\\\\\"\\\\n    run_outside_git_env lake exe cache get\\\\n  elif [ \\\\\\\"${MIPSTARRE_CI_ALLOW_COLD_FETCH:-}\\\\\\\" = \\\\\\\"1\\\\\\\" ]; then\\\\n    note_warning \\\\\\\"no .lake/packages in $WORKTREE; materialising dependencies inside CI (MIPSTARRE_CI_ALLOW_COLD_FETCH=1)\\\\\\\"\\\\n    echo \\\\\\\"+ lake exe cache get\\\\\\\"\\\\n    run_outside_git_env lake exe cache get\\\\n  else\\\\n    printf 'ERROR: %s has no .lake/packages.\\\\\\\\n' \\\\\\\"$WORKTREE\\\\\\\"\\\\n    printf 'Bootstrap the worktree first (local/bin/worktree-setup.sh), which also carries\\\\\\\\n'\\\\n    printf 'the ProofWidgets prune workaround that only bites on package-free trees.\\\\\\\\n'\\\\n    printf 'Override with MIPSTARRE_CI_ALLOW_COLD_FETCH=1 if you know the tree is clean.\\\\\\\\n'\\\\n    exit \\\\\\\"$EXIT_TOOL_MISSING\\\\\\\"\\\\n  fi\\\\n\\\\n  echo \\\\\\\"+ lake build\\\\\\\"\\\\n  run_outside_git_env lake build\\\\n\\\\n  # pr-ci.yml:155-156\\\\n  echo \\\\\\\"+ lake build MIPStarRE.LDT.Test.AxiomAudit\\\\\\\"\\\\n  run_outside_git_env lake build MIPStarRE.LDT.Test.AxiomAudit\\\\n\\\\n  # pr-ci.yml:158-159\\\\n  echo \\\\\\\"+ scripts/comparator/check_challenge_drift.py\\\\\\\"\\\\n  run_outside_git_env python3 scripts/comparator/check_challenge_drift.py --root .\\\\n}\\\\n\\\\nstep_blueprint_render() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  require_tool leanblueprint \\\\\\\"pipx install leanblueprint && pipx inject --include-apps --force leanblueprint plastex\\\\\\\"\\\\n\\\\n  # pr-ci.yml:210-218.  The PDF pass is what catches undefined macros; it needs\\\\n  # a TeX installation the CI runner apt-installs and a laptop may not have.\\\\n  if command -v latexmk >/dev/null 2>&1 || command -v xelatex >/dev/null 2>&1; then\\\\n    _pdf=\\\\\\\"blueprint/print/print.pdf\\\\\\\"\\\\n    if ! rm -f \\\\\\\"$_pdf\\\\\\\"; then\\\\n      echo \\\\\\\"ERROR: could not remove stale $_pdf before rendering\\\\\\\"\\\\n      exit 1\\\\n    fi\\\\n    echo \\\\\\\"+ (cd blueprint/src && latexmk -interaction=nonstopmode -halt-on-error\\\\\\\"\\\\n    echo \\\\\\\"    -file-line-error -output-directory=../print)\\\\\\\"\\\\n    if ! ( cd blueprint/src && run_outside_git_env latexmk \\\\\\\\\\\\n        -interaction=nonstopmode -halt-on-error -file-line-error \\\\\\\\\\\\n        -output-directory=../print ); then\\\\n      echo \\\\\\\"ERROR: latexmk failed to render the blueprint PDF\\\\\\\"\\\\n      exit 1\\\\n    fi\\\\n    if [ ! -s \\\\\\\"$_pdf\\\\\\\" ]; then\\\\n      echo \\\\\\\"ERROR: latexmk produced no blueprint PDF\\\\\\\"\\\\n      exit 1\\\\n    fi\\\\n    _bbl=\\\\\\\"blueprint/print/print.bbl\\\\\\\"\\\\n    if [ -e \\\\\\\"$_bbl\\\\\\\" ]; then\\\\n      if ! cp \\\\\\\"$_bbl\\\\\\\" blueprint/src/web.bbl; then\\\\n        echo \\\\\\\"ERROR: could not refresh blueprint/src/web.bbl from $_bbl\\\\\\\"\\\\n        exit 1\\\\n      fi\\\\n    fi\\\\n  else\\\\n    note_warning \\\\\\\"no latexmk/xelatex on PATH; skipped blueprint PDF rendering; \\\\\\\\\\\\nundefined-macro check did not run\\\\\\\"\\\\n  fi\\\\n\\\\n  # pr-ci.yml:222-223: web.bbl is not committed and is regenerated from the\\\\n  # \\\\\\\\cite keys in the blueprint sources.\\\\n  if command -v texra-blueprint >/dev/null 2>&1; then\\\\n    echo \\\\\\\"+ texra-blueprint bbl\\\\\\\"\\\\n    run_outside_git_env texra-blueprint bbl\\\\n  else\\\\n    note_warning \\\\\\\"texra-blueprint not installed; skipped 'texra-blueprint bbl' (paper-gap cite keys may render unresolved)\\\\\\\"\\\\n  fi\\\\n\\\\n  # pr-ci.yml:225-243.  ^ERROR: is a hard failure; 'WARNING: File not found:'\\\\n  # is advisory.  Keep exit-code semantics, not annotation semantics.\\\\n  _web_log=\\\\\\\"$RUN_TMP/blueprint-web.txt\\\\\\\"\\\\n  if command -v texra-blueprint >/dev/null 2>&1; then\\\\n    echo \\\\\\\"+ (cd blueprint && texra-blueprint web)\\\\\\\"\\\\n    ( cd blueprint && run_outside_git_env texra-blueprint web 2>&1 ) | tee \\\\\\\"$_web_log\\\\\\\"\\\\n  else\\\\n    echo \\\\\\\"+ (cd blueprint && leanblueprint web)\\\\\\\"\\\\n    ( cd blueprint && run_outside_git_env leanblueprint web 2>&1 ) | tee \\\\\\\"$_web_log\\\\\\\"\\\\n  fi\\\\n\\\\n  if grep -q '^ERROR:' \\\\\\\"$_web_log\\\\\\\"; then\\\\n    echo \\\\\\\"ERROR: blueprint has unresolved labels (see the ERROR lines above)\\\\\\\"\\\\n    exit 1\\\\n  fi\\\\n  if grep -q 'WARNING: File not found:' \\\\\\\"$_web_log\\\\\\\"; then\\\\n    note_warning \\\\\\\"blueprint has missing file references (see WARNING lines in the blueprint-render log)\\\\\\\"\\\\n  fi\\\\n}\\\\n\\\\nstep_paper_gaps() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  require_tool texra-blueprint \\\\\\\"pipx install 'git+https://github.com/LionSR/texra-blueprint@v0.3.8'\\\\\\\"\\\\n  # pr-ci.yml:270-271\\\\n  echo \\\\\\\"+ texra-blueprint --root . paper-gaps check\\\\\\\"\\\\n  run_outside_git_env texra-blueprint --root . paper-gaps check\\\\n}\\\\n\\\\nstep_blueprint_sync() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  # pr-ci.yml:294-301\\\\n  echo \\\\\\\"+ python3 -m unittest discover -s scripts/tests -p 'test_*.py'\\\\\\\"\\\\n  run_outside_git_env python3 -m unittest discover -s scripts/tests -p 'test_*.py'\\\\n\\\\n  echo \\\\\\\"+ scripts/blueprint_lean_sync.py --update-lean-decls\\\\\\\"\\\\n  run_outside_git_env python3 scripts/blueprint_lean_sync.py --root . --update-lean-decls\\\\n\\\\n  echo \\\\\\\"+ scripts/blueprint_lean_sync.py --ci\\\\\\\"\\\\n  run_outside_git_env python3 scripts/blueprint_lean_sync.py --root . --ci\\\\n\\\\n  # pr-ci.yml:303-317.  This job deliberately has NO Lean setup: on GitHub it\\\\n  # exhausted the runner disk repeatedly.  Locally the reason is the machine's\\\\n  # single full-build budget (invariant 7) — the axiom audit is reported, not\\\\n  # run, and a human runs it inside the build lock.\\\\n  echo \\\\\\\"+ scripts/blueprint_axiom_audit_needed.py --base-ref $BASE_REF\\\\\\\"\\\\n  _needed=\\\\\\\"$(run_outside_git_env python3 scripts/blueprint_axiom_audit_needed.py --base-ref \\\\\\\"$BASE_REF\\\\\\\" --head-ref \\\\\\\"$HEAD_SHA\\\\\\\")\\\\\\\"\\\\n  if [ \\\\\\\"$_needed\\\\\\\" = \\\\\\\"true\\\\\\\" ]; then\\\\n    note_warning \\\\\\\"blueprint axiom audit is required for this diff: run 'python3 scripts/blueprint_leanok_axioms.py --ci' in a Lean environment\\\\\\\"\\\\n  else\\\\n    echo \\\\\\\"No proof-level \\\\\\\\\\\\\\\\leanok axiom audit is required for this diff.\\\\\\\"\\\\n  fi\\\\n}\\\\n\\\\nstep_file_length() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  # pr-ci.yml:339-340\\\\n  echo \\\\\\\"+ scripts/check_oversized_lean_files.py\\\\\\\"\\\\n  run_outside_git_env python3 scripts/check_oversized_lean_files.py --root .\\\\n}\\\\n\\\\nstep_proof_debt() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  # pr-ci.yml:362-371\\\\n  echo \\\\\\\"+ python3 -m unittest scripts/tests/test_audit_paper_facing_proof_debt.py\\\\\\\"\\\\n  run_outside_git_env python3 -m unittest scripts/tests/test_audit_paper_facing_proof_debt.py\\\\n\\\\n  echo \\\\\\\"+ scripts/audit_paper_facing_proof_debt.py --ci\\\\\\\"\\\\n  run_outside_git_env python3 scripts/audit_paper_facing_proof_debt.py --root . --ci\\\\n}\\\\n\\\\nstep_proof_evasion() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  # pr-ci.yml:407-412\\\\n  echo \\\\\\\"+ proof-evasion regression tests\\\\\\\"\\\\n  run_outside_git_env python3 -m unittest scripts/tests/test_check_duplicate_private_helpers.py\\\\n  run_outside_git_env python3 -m unittest scripts/tests/test_audit_conclusion_shaped_hypotheses.py\\\\n  run_outside_git_env python3 -m unittest scripts/tests/test_audit_lean_axiom_declarations.py\\\\n  run_outside_git_env python3 -m unittest scripts/tests/test_audit_unfaithful_markers.py\\\\n\\\\n  # pr-ci.yml:414-430\\\\n  echo \\\\\\\"+ scripts/audit_lean_axiom_declarations.py --ci\\\\\\\"\\\\n  run_outside_git_env python3 scripts/audit_lean_axiom_declarations.py --root . --ci\\\\n  echo \\\\\\\"+ scripts/audit_conclusion_shaped_hypotheses.py --ci\\\\\\\"\\\\n  run_outside_git_env python3 scripts/audit_conclusion_shaped_hypotheses.py --root . --ci\\\\n  echo \\\\\\\"+ scripts/audit_unfaithful_markers.py --ci\\\\\\\"\\\\n  run_outside_git_env python3 scripts/audit_unfaithful_markers.py --root . --ci\\\\n\\\\n  # pr-ci.yml:432-445: exit 1 from this one audit is advisory, anything else\\\\n  # is a real failure.  --github-annotations is dropped: ::warning lines are\\\\n  # inert outside Actions.\\\\n  echo \\\\\\\"+ scripts/check_duplicate_private_helpers.py --ci (advisory)\\\\\\\"\\\\n  set +e\\\\n  run_outside_git_env python3 scripts/check_duplicate_private_helpers.py --root . --ci\\\\n  _status=$?\\\\n  set -e\\\\n  if [ \\\\\\\"$_status\\\\\\\" -eq 1 ]; then\\\\n    note_warning \\\\\\\"duplicate private-helper candidates were reported; this audit is advisory\\\\\\\"\\\\n    _status=0\\\\n  fi\\\\n  if [ \\\\\\\"$_status\\\\\\\" -ne 0 ]; then\\\\n    exit \\\\\\\"$_status\\\\\\\"\\\\n  fi\\\\n}\\\\n\\\\nstep_statement_origin() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  # pr-ci.yml:466-471\\\\n  echo \\\\\\\"+ scripts/check_statement_paper_origin.py\\\\\\\"\\\\n  run_outside_git_env python3 scripts/check_statement_paper_origin.py --root .\\\\n}\\\\n\\\\nrun_step_body() {\\\\n  case \\\\\\\"$1\\\\\\\" in\\\\n    build) step_build ;;\\\\n    blueprint-render) step_blueprint_render ;;\\\\n    paper-gaps) step_paper_gaps ;;\\\\n    blueprint-sync) step_blueprint_sync ;;\\\\n    file-length) step_file_length ;;\\\\n    proof-debt) step_proof_debt ;;\\\\n    proof-evasion) step_proof_evasion ;;\\\\n    statement-origin) step_statement_origin ;;\\\\n    *) printf 'ERROR: no step body for %s\\\\\\\\n' \\\\\\\"$1\\\\\\\"; return 2 ;;\\\\n  esac\\\\n}\\\\n\\\\n# ---------------------------------------------------------------------------\\\\n# Dispatch\\\\n# ---------------------------------------------------------------------------\\\\n\\\\nFAILED=0\\\\nERRORED=0\\\\nBUILD_OUTCOME=\\\\\\\"\\\\\\\"\\\\nBUILD_SECONDS=0\\\\n\\\\nfor STEP in $STEP_NAMES; do\\\\n  LOG=\\\\\\\"$LOG_DIR/$STEP.log\\\\\\\"\\\\n\\\\n  if [ -n \\\\\\\"$ONLY_STEPS\\\\\\\" ]; then\\\\n    case \\\\\\\" $ONLY_STEPS \\\\\\\" in\\\\n      *\\\\\\\" $STEP \\\\\\\"*) ;;\\\\n      *)\\\\n        record_step \\\\\\\"$STEP\\\\\\\" skipped 0 \\\\\\\"$LOG\\\\\\\" 1 \\\\\\\"not selected by --only\\\\\\\"\\\\n        continue\\\\n        ;;\\\\n    esac\\\\n  fi\\\\n\\\\n  if [ \\\\\\\"$FORCE_ALL\\\\\\\" != 1 ] && ! step_gate \\\\\\\"$STEP\\\\\\\"; then\\\\n    record_step \\\\\\\"$STEP\\\\\\\" skipped 0 \\\\\\\"$LOG\\\\\\\" 1 \\\\\\\"no changes under $(step_gate_paths \\\\\\\"$STEP\\\\\\\")\\\\\\\"\\\\n    printf '  %-18s skipped\\\\\\\\n' \\\\\\\"$STEP\\\\\\\"\\\\n    continue\\\\n  fi\\\\n\\\\n  if [ \\\\\\\"$STEP\\\\\\\" = build ] && [ \\\\\\\"$SKIP_BUILD\\\\\\\" = 1 ]; then\\\\n    record_step \\\\\\\"$STEP\\\\\\\" skipped 0 \\\\\\\"$LOG\\\\\\\" 1 \\\\\\\"operator passed --skip-build\\\\\\\"\\\\n    printf '  %-18s skipped (--skip-build)\\\\\\\\n' \\\\\\\"$STEP\\\\\\\"\\\\n    continue\\\\n  fi\\\\n\\\\n  : > \\\\\\\"$LOG\\\\\\\"\\\\n  _step_start=\\\\\\\"$(epoch_now)\\\\\\\"\\\\n\\\\n  # Invariant 7: at most one full lake build machine-wide.  Only the build\\\\n  # step compiles; the audits are pure Python and take no lock.\\\\n  _locked=1\\\\n  if [ \\\\\\\"$STEP\\\\\\\" = build ]; then\\\\n    if acquire_lock \\\\\\\"$FULL_BUILD_LOCK\\\\\\\" \\\\\\\"$BUILD_LOCK_WAIT_S\\\\\\\" \\\\\\\"$BUILD_LOCK_STALE_S\\\\\\\" \\\\\\\"ci.sh pr=$PR_ID sha=$HEAD_SHA\\\\\\\"; then\\\\n      _locked=0\\\\n    else\\\\n      _locked=2\\\\n    fi\\\\n  else\\\\n    _locked=0\\\\n  fi\\\\n\\\\n  if [ \\\\\\\"$_locked\\\\\\\" = 2 ]; then\\\\n    {\\\\n      printf 'ERROR: could not take the machine-wide full-build lock %s within %ss.\\\\\\\\n' \\\\\\\"$FULL_BUILD_LOCK\\\\\\\" \\\\\\\"$BUILD_LOCK_WAIT_S\\\\\\\"\\\\n      printf 'Another full build (warmer or another worktree) is running; it is never killed.\\\\\\\\n'\\\\n    } >> \\\\\\\"$LOG\\\\\\\"\\\\n    _rc=\\\\\\\"$EXIT_TOOL_MISSING\\\\\\\"\\\\n  else\\\\n    set +e\\\\n    # Required commands must stop the step; the parent still collects its exit\\\\n    # code, releases the build lock, and continues with independent steps.\\\\n    ( set -e; run_step_body \\\\\\\"$STEP\\\\\\\" ) >> \\\\\\\"$LOG\\\\\\\" 2>&1\\\\n    _rc=$?\\\\n    set -e\\\\n    if [ \\\\\\\"$STEP\\\\\\\" = build ]; then\\\\n      release_lock \\\\\\\"$FULL_BUILD_LOCK\\\\\\\"\\\\n    fi\\\\n  fi\\\\n\\\\n  _elapsed=$(( $(epoch_now) - _step_start ))\\\\n\\\\n  if [ \\\\\\\"$_rc\\\\\\\" -eq 0 ]; then\\\\n    _outcome=success\\\\n    _note=\\\\\\\"\\\\\\\"\\\\n  elif [ \\\\\\\"$_rc\\\\\\\" -eq \\\\\\\"$EXIT_TOOL_MISSING\\\\\\\" ]; then\\\\n    _outcome=error\\\\n    _note=\\\\\\\"step could not run: $(grep -m1 '^ERROR:' \\\\\\\"$LOG\\\\\\\" 2>/dev/null || echo 'missing tool or prerequisite')\\\\\\\"\\\\n    ERRORED=1\\\\n  else\\\\n    _outcome=failure\\\\n    _note=\\\\\\\"exit $_rc\\\\\\\"\\\\n    FAILED=1\\\\n  fi\\\\n\\\\n  record_step \\\\\\\"$STEP\\\\\\\" \\\\\\\"$_outcome\\\\\\\" \\\\\\\"$_elapsed\\\\\\\" \\\\\\\"$LOG\\\\\\\" 1 \\\\\\\"$_note\\\\\\\"\\\\n  printf '  %-18s %-8s %5ss  %s\\\\\\\\n' \\\\\\\"$STEP\\\\\\\" \\\\\\\"$_outcome\\\\\\\" \\\\\\\"$_elapsed\\\\\\\" \\\\\\\"$LOG\\\\\\\"\\\\n\\\\n  if [ \\\\\\\"$STEP\\\\\\\" = build ]; then\\\\n    BUILD_OUTCOME=\\\\\\\"$_outcome\\\\\\\"\\\\n    BUILD_SECONDS=\\\\\\\"$_elapsed\\\\\\\"\\\\n  fi\\\\ndone\\\\n\\\\n# ---------------------------------------------------------------------------\\\\n# Manifest, PR record, telemetry\\\\n# ---------------------------------------------------------------------------\\\\n\\\\nRUN_FINISHED=\\\\\\\"$(iso_now)\\\\\\\"\\\\nRUN_SECONDS=$(( $(epoch_now) - RUN_START_EPOCH ))\\\\n\\\\nif [ \\\\\\\"$FAILED\\\\\\\" = 1 ]; then\\\\n  CONCLUSION=failure\\\\nelif [ \\\\\\\"$ERRORED\\\\\\\" = 1 ]; then\\\\n\\\",\\\"exit_code\\\":0,\\\"status\\\":\\\"completed\\\"}}\\n32549:+{\\\"type\\\":\\\"item.completed\\\",\\\"item\\\":{\\\"id\\\":\\\"item_28\\\",\\\"type\\\":\\\"command_execution\\\",\\\"command\\\":\\\"/bin/bash -lc 'cat docs/project_conventions.md'\\\",\\\"aggregated_output\\\":\\\"# MIPStarRE-local convention addenda\\\\n\\\\nThe canonical convention documents live in the `lean-conventions` skill of\\\\n[texra-ai/texra-lean-skills](https://github.com/texra-ai/texra-lean-skills)\\\\n(auto-installed for Claude Code sessions via `.claude/settings.json`; other\\\\nagents: clone the repository and symlink the skill directories, per its\\\\nREADME). This file holds only\\\\nMIPStarRE's project-local facts — it restates no shared rule, and shared\\\\nrules never move here.\\\\n\\\\n## Style (MATHLIB_style)\\\\n\\\\n### Linter warnings\\\\n\\\\nDo not mask linter warnings instead of fixing them. A cleanup PR should not add\\\\nbroad `set_option linter.<name> false` blocks, and especially not file-wide\\\\nblocks, just to make the build output quieter. Linters exist to expose real\\\\nmaintenance problems; hiding them makes later proof work and review harder.\\\\n\\\\nFix the warning at its source whenever possible:\\\\n\\\\n- wrap long lines rather than disabling `linter.style.longLine`;\\\\n- remove or narrow unused variables, section variables, and unused typeclass\\\\n  assumptions rather than disabling the corresponding unused-* linter;\\\\n- remove unused `simp` arguments rather than disabling `linter.unusedSimpArgs`;\\\\n- rewrite proof terms or state the simplified goal explicitly rather than\\\\n  silencing `linter.flexible`.\\\\n\\\\nIf a linter warning is a genuine false positive or a temporary porting\\\\nexception, use the narrowest possible scope, preferably\\\\n`set_option linter.<name> false in <decl>`, and add a short nearby explanation.\\\\nSuch exceptions should be rare and reviewable. Never use linter suppression as\\\\nthe main mechanism for a linter-warning cleanup PR.\\\\n\\\\n## PR review (MATHLIB_pr-review)\\\\n\\\\n### Source-faithfulness checks\\\\n\\\\nFor this repository, the first review question is whether a paper-facing Lean\\\\nstatement still represents the cited result in `references/ldt-paper/`.  Before\\\\napplying the general mathlib review checklist in the lean-conventions\\\\n`MATHLIB_pr-review` reference, compare every changed\\\\nsource-labelled theorem, lemma, proposition, corollary, or definition with the\\\\ncorresponding paper statement and the active blueprint entry.\\\\n\\\\nReject a paper-facing statement if it has acquired a non-paper bridge, residual,\\\\nrepair, package, producer, proof-obligation, assumptions-bundle, hypotheses-bundle,\\\\nor arbitrary implication hypothesis.  Necessary boundary hypotheses, such as\\\\npositivity for division or nonemptiness of a finite type, may be faithful formal\\\\nencodings of implicit paper assumptions, but they should be documented when\\\\nmathematically load-bearing.\\\\n\\\\nReviewers should also inspect `\\\\\\\\lean{}` and `\\\\\\\\leanok` links.  A source-labelled\\\\nblueprint entry should point to the source theorem or its faithful construction\\\\ntheorem, not to conditional helpers whose assumptions are proof obligations.\\\\nAuxiliary Lean declarations may be recorded in a separate remark, provided the\\\\nremark states that they are not additional hypotheses in the paper theorem.\\\\n\\\\n## Proof integrity (PROOF_INTEGRITY)\\\\n\\\\n### Companion document\\\\n\\\\n> **Companion document:** [`anti_patterns.md`](./anti_patterns.md) catalogues\\\\n> subtler proof-evasion patterns that pass every blocker check in the\\\\n> lean-conventions `PROOF_INTEGRITY` reference yet still\\\\n> fail to prove the claimed mathematics (conclusion-shaped hypotheses,\\\\n> definitional sleight-of-hand, zero-fallback branches, trivial default\\\\n> witnesses, Mathlib-bypass castles, external `*Statement` smuggles).\\\\n> Consult it alongside this file during review.\\\\n\\\\n### Project paper-realignment protocol\\\\n\\\\nThe canonical paper-realignment exception in the lean-conventions\\\\n`PROOF_INTEGRITY` reference is instantiated here as\\\\nfollows (the protocol and the `**Unfaithful:**` marker are described in\\\\n`AGENTS.md`):\\\\n\\\\n> **Paper-realignment exception:** When a PR is explicitly realigning a\\\\n> source-labelled declaration with `references/ldt-paper/`, the `sorry`\\\\n> blocker of the lean-conventions `PROOF_INTEGRITY` reference may be\\\\n> temporarily relaxed for the affected proof bodies.  The\\\\n> PR must restore the source-faithful public statement, name the remaining proof\\\\n> obligation as a theorem or lemma, and cite the paper passage plus the\\\\n> tracking issue or paper-gap note.  A theorem whose proof still depends on a\\\\n> known non-paper bridge, residual, repair input, obligation structure, or\\\\n> conditional helper\\\\n> must carry the `**Unfaithful:**` docstring marker described in `AGENTS.md`.\\\\n> Review such PRs against statement faithfulness and the documented discharge\\\\n> plan, not merely against the temporary `sorry` count.\\\\n\\\\n### Axiom policy\\\\n\\\\nWhen an external mathematical result must remain unformalized temporarily,\\\\nprefer a caller-supplied `Prop` hypothesis over a global `axiom`\\\\ndeclaration, and add a regression check (for example a\\\\n`Lean.collectAxioms`-based assertion, as in\\\\n`MIPStarRE.LDT.Test.AxiomAudit`) so later refactors cannot silently widen\\\\nthe axiomatic base.\\\\n\\\\nThis preference does not license proposition inputs on source-labelled paper\\\\ntheorems.  If the cited paper theorem does not assume the proposition, a\\\\ncaller-supplied `Prop` hypothesis is an additional theorem hypothesis, not a\\\\nproof of the paper statement.  Use such hypotheses only for explicitly\\\\nconditional auxiliary results, and keep the source-labelled theorem statement\\\\nfaithful to the paper.\\\\n\\\\n### Scaffolding that blocks real formalization\\\\n\\\\nThis is a subtle but critical failure mode: **scaffolding definitions or\\\\ntheorem statements that do not faithfully represent the actual mathematics**,\\\\nmaking them impossible to connect to real Mathlib-based proofs.\\\\n\\\\nSigns to watch for:\\\\n\\\\n- Custom type definitions for objects that already exist in Mathlib (e.g.,\\\\n  defining a custom `Measurement` type instead of using Mathlib's\\\\n  `MeasureTheory` or operator algebra API)\\\\n- Theorem statements whose hypotheses or conclusions use project-local types\\\\n  that are not definitionally equal to or coercible from the Mathlib versions\\\\n- Scaffolded definitions that compile but encode the wrong mathematical\\\\n  semantics (e.g., a \\\\\\\"projective measurement\\\\\\\" definition that does not enforce\\\\n  the correct positivity or completeness conditions)\\\\n- Intermediate lemmas stated in terms of scaffolding types that cannot be\\\\n  connected upstream to Mathlib's API without reproving everything\\\\n- Definitions that \\\\\\\"work\\\\\\\" for `sorry`-based proofs but fail when you try to\\\\n  fill in real proofs using Mathlib lemmas (type mismatches, missing instances,\\\\n  incompatible universes)\\\\n\\\\nWhen reviewing scaffolded code, ask: **Can a real proof be built on top of\\\\nthis?** If the types, instances, and API surface don't align with Mathlib, the\\\\nscaffolding is actively harmful — it creates technical debt that blocks\\\\nprogress rather than enabling it.\\\\n\\\\n### Paper-labelled theorem statement drift\\\\n\\\\nA theorem advertised as the Lean formalization of a paper theorem is a blocker\\\\nif its public statement has drifted from the cited paper statement.\\\\nChanging a theorem away from the statement in `references/ldt-paper/` is\\\\nstrongly discouraged unless it is forced by faithful formal encoding or by a\\\\ndocumented mathematical necessity.\\\\n\\\\nThe most common failure mode is replacing an unformalized proof step by an\\\\nextra hypothesis on the theorem itself.  This produces a true conditional\\\\ntheorem, but it is not the theorem stated in the paper.  In particular, do not\\\\nrepair a theorem such as `mainFormal` by adding assumptions named\\\\n`BridgeHypotheses`, `Input`, `Residual`, `Package`, `RepairInput`, `Producer`,\\\\ngeneric `Hypotheses` or `Assumptions` bundles, or similar, unless those\\\\nassumptions are explicitly present in the cited paper statement.\\\\n\\\\nConditional helpers are a last-resort quarantine for proof work that cannot yet\\\\nbe closed.  Before introducing one, state the missing intermediate fact as a\\\\nnamed lemma or theorem to be proved from the paper hypotheses.  A conditional\\\\nhelper is permitted only when it has a paper-gap note or tracking issue, a named\\\\nobligation-discharger target, and an explicit removal plan.  Its name must show\\\\nthat it is conditional, for example with `_of_...`, `_assuming_...`, or\\\\n`conditional...`.  It must not be the declaration used by a source-labelled\\\\nblueprint theorem with `\\\\\\\\leanok`.\\\\n\\\\nExisting bridge hypotheses should be treated as proof debt.  Mine their proofs\\\\nfor reusable arguments, but do not keep a paper-labelled theorem in a\\\\nstrengthened form merely because the conditional version compiles.  If the\\\\nbridge data cannot be derived from the paper hypotheses, the correct repair is\\\\nto restore the paper-aligned theorem statement and leave the missing proof as a\\\\ntracked `sorry`, rather than to keep the extra assumption on the theorem.\\\\n\\\\nNot every explicit Lean hypothesis is statement drift.  Side conditions needed\\\\nto encode the paper's domain, such as nonemptiness, decidability, field-model\\\\ninstances, positivity of parameters, or denominator nonvanishing, may be\\\\nfaithful when the paper uses the corresponding objects without comment.  These\\\\nconditions should still be reviewed.  The issue is whether the hypothesis is\\\\nmathematical domain data implicit in the source, or an unproved intermediate\\\\nstep of the source proof.\\\\n\\\\nFor every paper-labelled theorem change, require a statement integrity audit:\\\\n\\\\n- paper assumptions versus Lean assumptions;\\\\n- paper conclusion versus Lean conclusion;\\\\n- verdict: exact, faithful boundary hypotheses, extra assumptions, weakened\\\\n  conclusion, or strengthened conclusion.\\\\n\\\\n### Source-statement proof gaps\\\\n\\\\n**For source-statement proof gaps**: Read\\\\n[`paper-gaps/proof-gap-protocol.tex`](paper-gaps/proof-gap-protocol.tex) when a\\\\nproof is blocked by a bridge, residual, repair, input, package, or obligation\\\\nstructure.  It explains when to introduce an internal obligation theorem, why\\\\nconditional helpers are exceptional temporary quarantine objects, and why a\\\\ntracked `sorry` is preferable to a strengthened source theorem statement.\\\\n\\\",\\\"exit_code\\\":0,\\\"status\\\":\\\"completed\\\"}}\\n32551:+{\\\"type\\\":\\\"item.completed\\\",\\\"item\\\":{\\\"id\\\":\\\"item_29\\\",\\\"type\\\":\\\"command_execution\\\",\\\"command\\\":\\\"/bin/bash -lc 'nl -ba scripts/tests/test_ci_step_failures.py'\\\",\\\"aggregated_output\\\":\\\"     1\\\\t#!/usr/bin/env python3\\\\n     2\\\\t\\\\\\\"\\\\\\\"\\\\\\\"Exercise CI step failures through the real driver with offline tool fixtures.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n     3\\\\t\\\\n     4\\\\tfrom __future__ import annotations\\\\n     5\\\\t\\\\n     6\\\\timport json\\\\n     7\\\\timport os\\\\n     8\\\\timport shutil\\\\n     9\\\\timport subprocess\\\\n    10\\\\tfrom pathlib import Path\\\\n    11\\\\t\\\\n    12\\\\tfrom scripts.tests import test_github_workflow as workflow\\\\n    13\\\\t\\\\n    14\\\\t\\\\n    15\\\\tFAKE_COMMAND = r'''#!/u