vate_helpers.py --ci (advisory)\\\\\\\"\\\\n  set +e\\\\n  run_outside_git_env python3 scripts/check_duplicate_private_helpers.py --root . --ci\\\\n  _status=$?\\\\n  set -e\\\\n  if [ \\\\\\\"$_status\\\\\\\" -eq 1 ]; then\\\\n    note_warning \\\\\\\"duplicate private-helper candidates were reported; this audit is advisory\\\\\\\"\\\\n    _status=0\\\\n  fi\\\\n  if [ \\\\\\\"$_status\\\\\\\" -ne 0 ]; then\\\\n    exit \\\\\\\"$_status\\\\\\\"\\\\n  fi\\\\n}\\\\n\\\\nstep_statement_origin() {\\\\n  cd \\\\\\\"$WORKTREE\\\\\\\"\\\\n  # pr-ci.yml:466-471\\\\n  echo \\\\\\\"+ scripts/check_statement_paper_origin.py\\\\\\\"\\\\n  run_outside_git_env python3 scripts/check_statement_paper_origin.py --root .\\\\n}\\\\n\\\\nrun_step_body() {\\\\n  case \\\\\\\"$1\\\\\\\" in\\\\n\\\",\\\"exit_code\\\":0,\\\"status\\\":\\\"completed\\\"}}\\n32627:+{\\\"type\\\":\\\"item.completed\\\",\\\"item\\\":{\\\"id\\\":\\\"item_20\\\",\\\"type\\\":\\\"command_execution\\\",\\\"command\\\":\\\"/bin/bash -lc 'cat .githooks/pre-commit'\\\",\\\"aggregated_output\\\":\\\"#!/bin/sh\\\\nset -eu\\\\n\\\\nROOT=\\\\\\\"$(git rev-parse --show-toplevel)\\\\\\\"\\\\ncd \\\\\\\"$ROOT\\\\\\\"\\\\nHOOK_ROOT=\\\\\\\"$(CDPATH= cd -- \\\\\\\"$(dirname \\\\\\\"$0\\\\\\\")/..\\\\\\\" && pwd)\\\\\\\"\\\\nGIT_LOCAL_ENV_VARS=\\\\\\\"$(git rev-parse --local-env-vars)\\\\\\\"\\\\n\\\\nrun_without_git_local_env() (\\\\n  # Git exports repository-local variables while running hooks.  Several script\\\\n  # tests create temporary repositories; keep those tests independent of this\\\\n  # checkout.\\\\n  unset $GIT_LOCAL_ENV_VARS\\\\n  \\\\\\\"$@\\\\\\\"\\\\n)\\\\n\\\\n# A merge commit can be syntactically valid while its index has been reset to\\\\n# the first-parent tree.  That failure mode silently discarded clean incoming\\\\n# additions on issue-109 and issue-110 (issue #222).  Check the pending index\\\\n# before every other gate, including the documented blanket hook bypass: a\\\\n# missing incoming path is valid only when the branch deleted a base path.\\\\nMERGE_HEAD_PATH=\\\\\\\"$(git rev-parse --git-path MERGE_HEAD)\\\\\\\"\\\\nif [ -f \\\\\\\"$MERGE_HEAD_PATH\\\\\\\" ]; then\\\\n  echo \\\\\\\"MIPStarRE pre-commit: checking the merge result for silent incoming loss.\\\\\\\"\\\\n  python3 \\\\\\\"$HOOK_ROOT/local/bin/merge_loss_guard.py\\\\\\\" --repo \\\\\\\"$ROOT\\\\\\\"\\\\nfi\\\\n\\\\n# Scope-control guard (EVOLUTION.md 2026-09-01, the issue-0007 overbuild):\\\\n# workflow scaffolding is budgeted at <=1000 changed lines per commit (400 until the owner raised it on 2026-09-05).  This is\\\\n# mechanical enforcement — repeated verbal correction of scaffolding bloat did\\\\n# not stick, so the budget lives in the hook.  The override env var is granted\\\\n# by the OWNER per commit, never self-granted by an agent session.  Runs\\\\n# before the ACMR early-exit so deletion-only commits are counted too\\\\n# (numstat includes deletions; PR 7 round 3, F8), and before the\\\\n# MIPSTARRE_SKIP_HOOKS exit so a blanket hook skip cannot launder the\\\\n# owner-only budget override.\\\\n# A merge that carries main stages already-reviewed content.  A merge head\\\\n# contained in github/main measures the budget against MERGE_HEAD; a merge head\\\\n# that contains github/main (a parent branch of a stack that already merged\\\\n# main; owner decision 2026-09-05) measures it against github/main, so inherited\\\\n# main content counts zero while the PR's cumulative workflow diff and any\\\\n# side-branch content beyond main still count.  Any other side-branch merge\\\\n# stays budgeted against HEAD.\\\\nif [ -f \\\\\\\"$MERGE_HEAD_PATH\\\\\\\" ] &&\\\\n    git merge-base --is-ancestor MERGE_HEAD refs/remotes/github/main 2>/dev/null; then\\\\n  BUDGET_BASE=\\\\\\\"$(git rev-parse MERGE_HEAD)\\\\\\\"\\\\n  echo \\\\\\\"MIPStarRE pre-commit: main-history merge; budget measured against MERGE_HEAD.\\\\\\\"\\\\nelif [ -f \\\\\\\"$MERGE_HEAD_PATH\\\\\\\" ] &&\\\\n    git merge-base --is-ancestor refs/remotes/github/main MERGE_HEAD 2>/dev/null; then\\\\n  BUDGET_BASE=\\\\\\\"$(git rev-parse refs/remotes/github/main)\\\\\\\"\\\\n  echo \\\\\\\"MIPStarRE pre-commit: non-main merge carrying github/main; workflow-layer content beyond github/main is budgeted.\\\\\\\"\\\\nelse\\\\n  BUDGET_BASE=\\\\\\\"\\\\\\\"\\\\n  if [ -f \\\\\\\"$MERGE_HEAD_PATH\\\\\\\" ]; then\\\\n    echo \\\\\\\"MIPStarRE pre-commit: non-main merge; workflow-layer merge content is budgeted.\\\\\\\"\\\\n  fi\\\\nfi\\\\nINFRA_CHANGED=\\\\\\\"$(git diff --cached --numstat $BUDGET_BASE -- local/ .githooks/ \\\\\\\\\\\\n  scripts/tests/test_dispatch.py scripts/tests/test_github_workflow.py \\\\\\\\\\\\n  scripts/tests/test_lake_root.py scripts/tests/test_pre_push_hook.py \\\\\\\\\\\\n  scripts/tests/test_ready_packets.py scripts/tests/test_merge_loss_guard.py \\\\\\\\\\\\n  | awk '{added=$1; deleted=$2; if (added != \\\\\\\"-\\\\\\\") total+=added+deleted} END {print total+0}')\\\\\\\"\\\\nif [ \\\\\\\"${INFRA_CHANGED:-0}\\\\\\\" -gt 1000 ] && [ \\\\\\\"${MIPSTARRE_INFRA_OVERRIDE:-}\\\\\\\" != \\\\\\\"1\\\\\\\" ]; then\\\\n  echo \\\\\\\"MIPStarRE pre-commit: staged workflow-layer change is ${INFRA_CHANGED} lines (budget: 1000).\\\\\\\"\\\\n  echo \\\\\\\"Scope control (local/personas/main.md): the budget is PER EPISODE, not per\\\\\\\"\\\\n  echo \\\\\\\"commit — serial oversized commits are the same violation and show in the\\\\\\\"\\\\n  echo \\\\\\\"telemetry. Shrink the change, or ask the OWNER to authorize this commit\\\\\\\"\\\\n  echo \\\\\\\"with MIPSTARRE_INFRA_OVERRIDE=1 (self-granting it is a protocol breach).\\\\\\\"\\\\n  exit 1\\\\nfi\\\\n\\\\nif [ \\\\\\\"${MIPSTARRE_SKIP_HOOKS:-}\\\\\\\" = \\\\\\\"1\\\\\\\" ]; then\\\\n  echo \\\\\\\"MIPStarRE pre-commit hook skipped by MIPSTARRE_SKIP_HOOKS=1.\\\\\\\"\\\\n  exit 0\\\\nfi\\\\n\\\\nSTAGED_FILES=\\\\\\\"$(git diff --cached --name-only --diff-filter=ACMR)\\\\\\\"\\\\nif [ -z \\\\\\\"$STAGED_FILES\\\\\\\" ]; then\\\\n  exit 0\\\\nfi\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking staged whitespace.\\\\\\\"\\\\n# Paper mirrors under references/ are byte-faithful captures of external\\\\n# arXiv sources (see references/*/README.md); their inherited trailing\\\\n# whitespace is part of the fidelity claim and must not be \\\\\\\"fixed\\\\\\\", so they\\\\n# are exempt from the whitespace gate (local/protocols/EVOLUTION.md,\\\\n# 2026-08-30).\\\\ngit diff --cached --check -- ':(exclude)references/'\\\\n\\\\nif printf '%s\\\\\\\\n' \\\\\\\"$STAGED_FILES\\\\\\\" | grep -Eq '^scripts/(.*\\\\\\\\.py|tests/.*)$'; then\\\\n  echo \\\\\\\"MIPStarRE pre-commit: running scripts/tests unit tests.\\\\\\\"\\\\n  run_without_git_local_env python3 -m unittest discover -s scripts/tests -p 'test_*.py'\\\\nfi\\\\n\\\\nif printf '%s\\\\\\\\n' \\\\\\\"$STAGED_FILES\\\\\\\" | grep -Eq \\\\\\\\\\\\n  '^(blueprint/src/.*\\\\\\\\.(tex|sty|cls)|scripts/(check_blueprint_latex|tex_utils)\\\\\\\\.py|scripts/tests/test_check_blueprint_latex\\\\\\\\.py|\\\\\\\\.githooks/pre-commit)$'; then\\\\n  echo \\\\\\\"MIPStarRE pre-commit: checking blueprint LaTeX conventions.\\\\\\\"\\\\n  python3 scripts/check_blueprint_latex.py --root blueprint/src\\\\nfi\\\\n\\\\nif ! printf '%s\\\\\\\\n' \\\\\\\"$STAGED_FILES\\\\\\\" | grep -Eq \\\\\\\\\\\\n  '^(MIPStarRE/|MIPStarRE\\\\\\\\.lean|blueprint/src/|blueprint/lean_decls|scripts/(audit_new_proof_obligation_metadata|audit_paper_facing_proof_debt|audit_conclusion_shaped_hypotheses|audit_unfaithful_markers|audit_lean_axiom_declarations|check_blueprint_latex|check_paper_gap_note_style|check_statement_paper_origin|check_source_statement_changes|blueprint_lean_sync|lean_header_utils|tex_utils)\\\\\\\\.py|docs/(CONTRIBUTING|project_conventions|anti_patterns|blueprint_style_guide|formalization-patterns|proof_frontier_review)\\\\\\\\.md|docs/paper-gaps/|\\\\\\\\.github/(actions|prompts|workflows)/|AGENTS\\\\\\\\.md)'; then\\\\n  echo \\\\\\\"MIPStarRE pre-commit: no statement-integrity files staged.\\\\\\\"\\\\n  exit 0\\\\nfi\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking changed paper-gap note structure.\\\\\\\"\\\\npython3 scripts/check_paper_gap_note_style.py --root . --staged --ci\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking statement-like paper-origin citations.\\\\\\\"\\\\npython3 scripts/check_statement_paper_origin.py --root .\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking new proof-obligation metadata.\\\\\\\"\\\\npython3 scripts/audit_new_proof_obligation_metadata.py --root . --staged --ci\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking paper-facing proof-debt headers.\\\\\\\"\\\\necho \\\\\\\"MIPStarRE pre-commit: do not close proof gaps by adding non-paper bridge/package hypotheses.\\\\\\\"\\\\npython3 scripts/audit_paper_facing_proof_debt.py --root . --ci\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking conclusion-shaped hypotheses.\\\\\\\"\\\\npython3 scripts/audit_conclusion_shaped_hypotheses.py --root . --ci\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking unfaithful-dependency markers.\\\\\\\"\\\\npython3 scripts/audit_unfaithful_markers.py --root . --ci\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: checking explicit LDT axiom declarations.\\\\\\\"\\\\npython3 scripts/audit_lean_axiom_declarations.py --root . --ci\\\\n\\\\necho \\\\\\\"MIPStarRE pre-commit: ok.\\\\\\\"\\\\n\\\",\\\"exit_code\\\":0,\\\"status\\\":\\\"completed\\\"}}\\n32635:+{\\\"type\\\":\\\"item.completed\\\",\\\"item\\\":{\\\"id\\\":\\\"item_24\\\",\\\"type\\\":\\\"command_execution\\\",\\\"command\\\":\\\"/bin/bash -lc 'cat lakefile.toml MIPStarRE.lean MIPStarRE/QPBT.lean MIPStarRE/LDT/Test/AxiomAudit.lean'\\\",\\\"aggregated_output\\\":\\\"name = \\\\\\\"MIPStarRE\\\\\\\"\\\\nversion = \\\\\\\"0.1.0\\\\\\\"\\\\nkeywords = [\\\\\\\"math\\\\\\\"]\\\\ndefaultTargets = [\\\\\\\"MIPStarRE\\\\\\\"]\\\\n\\\\n[leanOptions]\\\\npp.unicode.fun = true # pretty-prints `fun a ↦ b`\\\\nrelaxedAutoImplicit = false\\\\nweak.linter.mathlibS